// Orden de ejecución de Unity (simplificado):

// 1. INICIALIZACIÓN
void Awake()    // Se llama primero, aunque el objeto esté desactivado. Ideal para inicializar referencias internas.
void OnEnable() // Se llama cuando el objeto se activa. Puede llamarse varias veces.
void Start()    // Se llama una sola vez, justo antes del primer frame. El objeto está activo.

// 2. BUCLE DE JUEGO (repetido cada frame)
void FixedUpdate()  // Frame de física (por defecto ~50 veces/seg). Usa para Rigidbody.
void Update()       // Cada frame visual. Usa para input y lógica de juego.
void LateUpdate()   // Después de Update. Ideal para cámaras que siguen al jugador.

// 3. DESTRUCCIÓN
void OnDisable()    // Cuando el objeto se desactiva.
void OnDestroy()    // Cuando el objeto es destruido definitivamente.

